var TIER_NAME = { hot:"热乎", warm:"温", cold:"凉" };
/* ── 盘上那两份静态文案（bf-13）：没有倒计时，所以两行都不随时间变化。
      PLATE_KEEP_TEXT 画在每盘食物下面，取代原来的「N.Ns 内送出」。 */
var PLATE_KEEP_TEXT = "∞ 可一直放着";

